import re


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the next `</title>`.

    Tag names are matched case-insensitively (`<TITLE>` works). The text is
    returned exactly as written, with no stripping or entity decoding.
    Returns "" if there is no `<title>`, or if it is never closed.
    The function works only on the given string and does no network access.
    """
    m = re.search(r"<title>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    return m.group(1) if m else ""


def test_basic_title() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title_returns_empty() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""


def test_empty_string_input() -> None:
    assert title_of("") == ""


def test_empty_title_element() -> None:
    assert title_of("<title></title>") == ""


def test_unclosed_title_returns_empty() -> None:
    assert title_of("<html><head><title>Oops</head></html>") == ""


def test_closing_tag_without_opening_returns_empty() -> None:
    assert title_of("<head>Oops</title></head>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><TITLE>Upper</TITLE></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  spaced out \n</title>") == "  spaced out \n"


def test_multiline_title() -> None:
    assert title_of("<title>line1\nline2</title>") == "line1\nline2"


def test_text_kept_verbatim_with_entities_and_unicode() -> None:
    assert title_of("<title>Tom &amp; Jerry – café</title>") == "Tom &amp; Jerry – café"


def test_title_not_at_start() -> None:
    html = "<!DOCTYPE html>\n<html>\n<head>\n<meta charset='utf-8'>\n<title>Deep</title>\n</head></html>"
    assert title_of(html) == "Deep"
